1	import { useState, useRef, useCallback } from "react";
2	import { Upload, FileText, CheckCircle2, XCircle, Loader2, X, RefreshCw } from "lucide-react";
3	import { Button } from "@/components/ui/button";
4	import { Progress } from "@/components/ui/progress";
5	import { toast } from "sonner";
6	import { supabase } from "@/integrations/supabase/client";
7	
8	// ─── Types ───────────────────────────────────────────────────────────────────
9	
10	type FileStatus = "pending" | "uploading" | "done" | "failed";
11	
12	interface FileEntry {
13	  file: File;
14	  status: FileStatus;
15	  error?: string;
16	}
17	
18	interface BulkUploadZoneProps {
19	  jobId: string;
20	  userId: string;
21	  onUploadComplete: () => void;
22	  maxFiles?: number;
23	  maxFileSize?: number; // MB
24	  disabled?: boolean;
25	}
26	
27	const ACCEPTED_TYPES = [
28	  "application/pdf",
29	  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
30	  "application/msword",
31	  "application/rtf",
32	  "text/plain",
33	];
34	
35	const ACCEPTED_EXTENSIONS = ".pdf,.docx,.doc,.rtf,.txt";
36	const CONCURRENCY = 5;
37	
38	// ─── Component ───────────────────────────────────────────────────────────────
39	
40	export default function BulkUploadZone({
41	  jobId,
42	  userId,
43	  onUploadComplete,
44	  maxFiles = 200,
45	  maxFileSize = 5,
46	  disabled = false,
47	}: BulkUploadZoneProps) {
48	  const [entries, setEntries] = useState<FileEntry[]>([]);
49	  const [dragOver, setDragOver] = useState(false);
50	  const [uploading, setUploading] = useState(false);
51	  const cancelRef = useRef(false);
52	
53	  const updateEntry = useCallback(
54	    (index: number, patch: Partial<FileEntry>) => {
55	      setEntries((prev) =>
56	        prev.map((e, i) => (i === index ? { ...e, ...patch } : e))
57	      );
58	    },
59	    []
60	  );
61	
62	  const addFiles = useCallback(
63	    (newFiles: File[]) => {
64	      const valid: File[] = [];
65	      for (const f of newFiles) {
66	        if (!ACCEPTED_TYPES.includes(f.type) && !f.name.match(/\.(pdf|docx|doc|rtf|txt)$/i)) {
67	          toast.error(`${f.name}: unsupported file type`);
68	          continue;
69	        }
70	        if (f.size > maxFileSize * 1024 * 1024) {
71	          toast.error(`${f.name}: exceeds ${maxFileSize}MB limit`);
72	          continue;
73	        }
74	        valid.push(f);
75	      }
76	
77	      setEntries((prev) => {
78	        const existingNames = new Set(prev.map((e) => e.file.name.toLowerCase()));
79	        const toAdd: FileEntry[] = [];
80	        for (const f of valid) {
81	          if (existingNames.has(f.name.toLowerCase())) continue;
82	          if (prev.length + toAdd.length >= maxFiles) {
83	            toast.error(`Maximum ${maxFiles} files allowed`);
84	            break;
85	          }
86	          existingNames.add(f.name.toLowerCase());
87	          toAdd.push({ file: f, status: "pending" });
88	        }
89	        return [...prev, ...toAdd];
90	      });
91	    },
92	    [maxFiles, maxFileSize]
93	  );
94	
95	  const handleDrop = useCallback(
96	    (e: React.DragEvent) => {
97	      e.preventDefault();
98	      setDragOver(false);
99	      if (disabled || uploading) return;
100	      addFiles(Array.from(e.dataTransfer.files));
101	    },
102	    [disabled, uploading, addFiles]
103	  );
104	
105	  const handleFileSelect = useCallback(
106	    (e: React.ChangeEvent<HTMLInputElement>) => {
107	      if (e.target.files) {
108	        addFiles(Array.from(e.target.files));
109	        e.target.value = "";
110	      }
111	    },
112	    [addFiles]
113	  );
114	
115	  const uploadSingle = async (
116	    entry: FileEntry,
117	    index: number
118	  ): Promise<boolean> => {
119	    if (cancelRef.current) return false;
120	
121	    updateEntry(index, { status: "uploading" });
122	
123	    try {
124	      const filePath = `${userId}/${jobId}/${Date.now()}_${entry.file.name}`;
125	
126	      const { error: uploadError } = await supabase.storage
127	        .from("resumes")
128	        .upload(filePath, entry.file);
129	
130	      if (uploadError) throw new Error(uploadError.message);
131	      if (cancelRef.current) return false;
132	
133	      const { error: insertError } = await (supabase as any)
134	        .from("resumes")
135	        .insert({
136	          job_id: jobId,
137	          filename: entry.file.name,
138	          file_path: filePath,
139	        });
140	
141	      if (insertError) {
142	        // If insert fails, clean up storage
143	        await supabase.storage.from("resumes").remove([filePath]).catch(() => {});
144	        throw new Error(insertError.message);
145	      }
146	
147	      updateEntry(index, { status: "done" });
148	      return true;
149	    } catch (err: unknown) {
150	      const message = err instanceof Error ? err.message : "Upload failed";
151	      updateEntry(index, { status: "failed", error: message });
152	      return false;
153	    }
154	  };
155	
156	  const runQueue = async (entriesToProcess: FileEntry[]) => {
157	    cancelRef.current = false;
158	    setUploading(true);
159	
160	    // Get indexes of pending entries in the current state snapshot
161	    // We need stable indexes from the full entries array
162	    const pendingIndexes: number[] = [];
163	    setEntries((prev) => {
164	      prev.forEach((e, i) => {
165	        if (e.status === "pending") pendingIndexes.push(i);
166	      });
167	      return prev;
168	    });
169	
170	    // Process in batches of CONCURRENCY
171	    let i = 0;
172	    const total = pendingIndexes.length;
173	    let doneCount = 0;
174	    let failCount = 0;
175	
176	    while (i < total && !cancelRef.current) {
177	      const batch = pendingIndexes.slice(i, i + CONCURRENCY);
178	
179	      // Snapshot current entries to pass to uploadSingle
180	      let currentEntries: FileEntry[] = [];
181	      setEntries((prev) => { currentEntries = prev; return prev; });
182	
183	      const results = await Promise.all(
184	        batch.map((idx) => uploadSingle(currentEntries[idx], idx))
185	      );
186	
187	      results.forEach((ok) => {
188	        if (ok) doneCount++;
189	        else failCount++;
190	      });
191	
192	      i += CONCURRENCY;
193	    }
194	
195	    setUploading(false);
196	
197	    if (cancelRef.current) {
198	      toast.error("Upload cancelled");
199	      return;
200	    }
201	
202	    if (doneCount > 0 && failCount === 0) {
203	      toast.success(`${doneCount} resume${doneCount !== 1 ? "s" : ""} uploaded`);
204	      onUploadComplete();
205	    } else if (doneCount > 0 && failCount > 0) {
206	      toast.error(`${doneCount} uploaded, ${failCount} failed`);
207	      onUploadComplete();
208	    } else {
209	      toast.error("All uploads failed");
210	    }
211	  };
212	
213	  const handleStartUpload = () => {
214	    const pending = entries.filter((e) => e.status === "pending");
215	    if (pending.length === 0) {
216	      toast.error("No files to upload");
217	      return;
218	    }
219	    runQueue(pending);
220	  };
221	
222	  const handleCancel = () => {
223	    cancelRef.current = true;
224	  };
225	
226	  const handleRetry = useCallback((index: number) => {
227	    setEntries((prev) =>
228	      prev.map((e, i) =>
229	        i === index ? { ...e, status: "pending", error: undefined } : e
230	      )
231	    );
232	  }, []);
233	
234	  const handleRemove = useCallback((index: number) => {
235	    setEntries((prev) => prev.filter((_, i) => i !== index));
236	  }, []);
237	
238	  const handleRetryAll = () => {
239	    setEntries((prev) =>
240	      prev.map((e) =>
241	        e.status === "failed" ? { ...e, status: "pending", error: undefined } : e
242	      )
243	    );
244	  };
245	
246	  const doneCount = entries.filter((e) => e.status === "done").length;
247	  const failedCount = entries.filter((e) => e.status === "failed").length;
248	  const uploadingCount = entries.filter((e) => e.status === "uploading").length;
249	  const pendingCount = entries.filter((e) => e.status === "pending").length;
250	  const totalCount = entries.length;
251	  const progressPct = totalCount > 0 ? Math.round((doneCount / totalCount) * 100) : 0;
252	
253	  return (
254	    <div className="space-y-3">
255	      {/* Drop zone */}
256	      <div
257	        className={`border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-all duration-200 flex flex-col items-center justify-center ${
258	          disabled || uploading
259	            ? "opacity-50 cursor-not-allowed border-border"
260	            : dragOver
261	            ? "border-primary bg-primary/5 scale-[1.01]"
262	            : "border-border hover:border-primary/50 hover:bg-primary/[0.02]"
263	        }`}
264	        onDragOver={(e) => {
265	          e.preventDefault();
266	          if (!disabled && !uploading) setDragOver(true);
267	        }}
268	        onDragLeave={() => setDragOver(false)}
269	        onDrop={handleDrop}
270	        onClick={() => {
271	          if (disabled || uploading) return;
272	          document.getElementById("bulk-file-input")?.click();
273	        }}
274	      >
275	        <div className="w-12 h-12 rounded-xl bg-muted flex items-center justify-center mb-3">
276	          <Upload className="h-6 w-6 text-primary" />
277	        </div>
278	        <p className="text-sm font-medium text-foreground mb-1">
279	          Drop up to {maxFiles} resumes here
280	        </p>
281	        <p className="text-xs text-muted-foreground">
282	          PDF, DOCX, DOC, RTF, TXT · {maxFileSize}MB each
283	        </p>
284	        <input
285	          id="bulk-file-input"
286	          type="file"
287	          className="hidden"
288	          multiple
289	          accept={ACCEPTED_EXTENSIONS}
290	          onChange={handleFileSelect}
291	          disabled={disabled || uploading}
292	        />
293	      </div>
294	
295	      {/* File list */}
296	      {entries.length > 0 && (
297	        <>
298	          <div className="border border-border rounded-lg overflow-hidden">
299	            {/* List header */}
300	            <div className="flex items-center justify-between px-3 py-2 bg-muted/40 border-b border-border">
301	              <span className="text-xs font-medium text-muted-foreground">
302	                {totalCount} file{totalCount !== 1 ? "s" : ""}
303	                {doneCount > 0 && ` · ${doneCount} done`}
304	                {failedCount > 0 && ` · ${failedCount} failed`}
305	                {uploadingCount > 0 && ` · ${uploadingCount} uploading`}
306	              </span>
307	              {failedCount > 0 && !uploading && (
308	                <button
309	                  onClick={handleRetryAll}
310	                  className="text-xs text-primary hover:text-primary/80 transition-colors flex items-center gap-1"
311	                >
312	                  <RefreshCw className="h-3 w-3" />
313	                  Retry all failed
314	                </button>
315	              )}
316	            </div>
317	
318	            {/* Scrollable file rows */}
319	            <div className="max-h-[300px] overflow-y-auto divide-y divide-border">
320	              {entries.map((entry, index) => (
321	                <div
322	                  key={`${entry.file.name}-${index}`}
323	                  className="flex items-center gap-2 px-3 py-2"
324	                >
325	                  {/* Status icon */}
326	                  <div className="shrink-0">
327	                    {entry.status === "done" && (
328	                      <CheckCircle2 className="h-4 w-4 text-emerald-500" />
329	                    )}
330	                    {entry.status === "failed" && (
331	                      <XCircle className="h-4 w-4 text-destructive" />
332	                    )}
333	                    {entry.status === "uploading" && (
334	                      <Loader2 className="h-4 w-4 text-primary animate-spin" />
335	                    )}
336	                    {entry.status === "pending" && (
337	                      <FileText className="h-4 w-4 text-muted-foreground" />
338	                    )}
339	                  </div>
340	
341	                  {/* Filename + error */}
342	                  <div className="flex-1 min-w-0">
343	                    <p
344	                      className={`text-xs truncate ${
345	                        entry.status === "done"
346	                          ? "text-muted-foreground"
347	                          : entry.status === "failed"
348	                          ? "text-destructive"
349	                          : "text-foreground"
350	                      }`}
351	                    >
352	                      {entry.file.name}
353	                    </p>
354	                    {entry.error && (
355	                      <p className="text-[11px] text-destructive truncate">
356	                        {entry.error}
357	                      </p>
358	                    )}
359	                  </div>
360	
361	                  {/* Actions */}
362	                  <div className="shrink-0 flex items-center gap-1">
363	                    {entry.status === "failed" && !uploading && (
364	                      <button
365	                        onClick={() => handleRetry(index)}
366	                        className="text-xs text-primary hover:text-primary/80 transition-colors"
367	                        title="Retry"
368	                      >
369	                        <RefreshCw className="h-3.5 w-3.5" />
370	                      </button>
371	                    )}
372	                    {(entry.status === "pending" || entry.status === "failed") &&
373	                      !uploading && (
374	                        <button
375	                          onClick={() => handleRemove(index)}
376	                          className="text-muted-foreground hover:text-foreground transition-colors"
377	                          title="Remove"
378	                        >
379	                          <X className="h-3.5 w-3.5" />
380	                        </button>
381	                      )}
382	                  </div>
383	                </div>
384	              ))}
385	            </div>
386	          </div>
387	
388	          {/* Progress bar — only visible during upload */}
389	          {uploading && (
390	            <div className="space-y-1.5">
391	              <div className="flex items-center justify-between text-xs text-muted-foreground">
392	                <span>
393	                  {doneCount} / {totalCount} uploaded
394	                </span>
395	                <span>{progressPct}%</span>
396	              </div>
397	              <Progress value={progressPct} className="h-2" />
398	            </div>
399	          )}
400	
401	          {/* Action row */}
402	          <div className="flex items-center gap-2">
403	            {!uploading ? (
404	              <>
405	                <Button
406	                  size="sm"
407	                  className="gap-1.5"
408	                  onClick={handleStartUpload}
409	                  disabled={pendingCount === 0 && failedCount === 0}
410	                >
411	                  <Upload className="h-4 w-4" />
412	                  Upload {pendingCount > 0 ? pendingCount : failedCount} File
413	                  {(pendingCount > 1 || failedCount > 1) ? "s" : ""}
414	                </Button>
415	                <Button
416	                  variant="ghost"
417	                  size="sm"
418	                  className="text-muted-foreground"
419	                  onClick={() => setEntries([])}
420	                >
421	                  Clear all
422	                </Button>
423	              </>
424	            ) : (
425	              <Button
426	                variant="outline"
427	                size="sm"
428	                className="gap-1.5 text-destructive hover:text-destructive"
429	                onClick={handleCancel}
430	              >
431	                <X className="h-4 w-4" />
432	                Cancel
433	              </Button>
434	            )}
435	          </div>
436	        </>
437	      )}
438	    </div>
439	  );
440	}
