const addRawFiles = useCallback(
  (validFiles: File[]) => {
    setEntries((prev) => {
      const existingNames = new Set(prev.map((e) => e.file.name.toLowerCase()));
      const toAdd: FileEntry[] = [];
      for (const f of validFiles) {
        if (existingNames.has(f.name.toLowerCase())) continue;
        if (prev.length + toAdd.length >= maxFiles) {
          toast.error(`Maximum ${maxFiles} files allowed`);
          break;
        }
        existingNames.add(f.name.toLowerCase());
        toAdd.push({ file: f, status: "pending" });
      }
      return [...prev, ...toAdd];
    });
  },
  [maxFiles]
);

const addFiles = useCallback(
  async (newFiles: File[]) => {
    const valid: File[] = [];
    const zipFiles: File[] = [];

    for (const f of newFiles) {
      const isZip = f.name.toLowerCase().endsWith(".zip") ||
        f.type === "application/zip" ||
        f.type === "application/x-zip-compressed";

      if (isZip) {
        zipFiles.push(f);
        continue;
      }

      if (!ACCEPTED_TYPES.includes(f.type) && !f.name.match(RESUME_EXTENSIONS)) {
        toast.error(`${f.name}: unsupported file type`);
        continue;
      }
      if (f.size > maxFileSize * 1024 * 1024) {
        toast.error(`${f.name}: exceeds ${maxFileSize}MB limit`);
        continue;
      }
      valid.push(f);
    }

    if (valid.length > 0) addRawFiles(valid);

    // Extract resume files from zip archives
    for (const zipFile of zipFiles) {
      try {
        const JSZip = (await import("jszip")).default;
        const zip = await JSZip.loadAsync(zipFile);
        const extracted: File[] = [];

        await Promise.all(
          Object.entries(zip.files).map(async ([name, entry]) => {
            if (entry.dir) return;
            if (!RESUME_EXTENSIONS.test(name)) return;
            // Skip macOS resource fork files
            if (name.startsWith("__MACOSX/") || name.startsWith("._")) return;

            const blob = await entry.async("blob");
            const filename = name.split("/").pop() ?? name;
            const ext = filename.split(".").pop()?.toLowerCase() ?? "";
            const mimeMap: Record<string, string> = {
              pdf: "application/pdf",
              docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
              doc: "application/msword",
              rtf: "application/rtf",
              txt: "text/plain",
            };
            const file = new File([blob], filename, { type: mimeMap[ext] ?? "application/octet-stream" });

            if (file.size > maxFileSize * 1024 * 1024) {
              toast.error(`${filename}: exceeds ${maxFileSize}MB limit`);
              return;
            }
            extracted.push(file);
          })
        );

        if (extracted.length > 0) {
          addRawFiles(extracted);
          toast.success(`Extracted ${extracted.length} resume${extracted.length !== 1 ? "s" : ""} from ${zipFile.name}`);
        } else {
          toast.error(`${zipFile.name}: no supported resume files found`);
        }
      } catch {
        toast.error(`${zipFile.name}: failed to extract ZIP`);
      }
    }
  },
  [maxFiles, maxFileSize, addRawFiles]
);

