import { useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export interface CandidateTag {
  id: string;
  resume_id: string;
  job_id: string;
  tag: string;
  color: string;
  created_by: string | null;
  created_at: string;
}

const QUERY_KEY = (jobId: string) => ["candidate-tags", jobId];

export function useCandidateTags(jobId: string | null) {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  const { data: tags = [], isLoading } = useQuery<CandidateTag[]>({
    queryKey: QUERY_KEY(jobId ?? ""),
    queryFn: async () => {
      if (!jobId) return [];
      const { data, error } = await (supabase as any)
        .from("candidate_tags")
        .select("*")
        .eq("job_id", jobId)
        .order("created_at", { ascending: true });
      if (error) throw error;
      return (data ?? []) as CandidateTag[];
    },
    enabled: !!jobId,
    staleTime: 30_000,
  });

  // Real-time subscription
  useEffect(() => {
    if (!jobId) return;

    const channel = supabase
      .channel(`candidate-tags-${jobId}`)
      .on(
        "postgres_changes" as any,
        {
          event: "*",
          schema: "public",
          table: "candidate_tags",
          filter: `job_id=eq.${jobId}`,
        },
        () => {
          queryClient.invalidateQueries({ queryKey: QUERY_KEY(jobId) });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [jobId, queryClient]);

  const addTagMutation = useMutation({
    mutationFn: async ({
      resumeId,
      tag,
      color = "#6366f1",
    }: {
      resumeId: string;
      tag: string;
      color?: string;
    }) => {
      if (!jobId || !user) throw new Error("Missing jobId or user");
      const { data, error } = await (supabase as any)
        .from("candidate_tags")
        .insert({
          resume_id: resumeId,
          job_id: jobId,
          tag: tag.trim(),
          color,
          created_by: user.id,
        })
        .select()
        .single();
      if (error) throw error;
      return data as CandidateTag;
    },
    onSuccess: () => {
      if (jobId) queryClient.invalidateQueries({ queryKey: QUERY_KEY(jobId) });
    },
  });

  const removeTagMutation = useMutation({
    mutationFn: async (tagId: string) => {
      const { error } = await (supabase as any)
        .from("candidate_tags")
        .delete()
        .eq("id", tagId);
      if (error) throw error;
    },
    onSuccess: () => {
      if (jobId) queryClient.invalidateQueries({ queryKey: QUERY_KEY(jobId) });
    },
  });

  const tagsForResume = (resumeId: string): CandidateTag[] =>
    tags.filter((t) => t.resume_id === resumeId);

  return {
    tags,
    isLoading,
    tagsForResume,
    addTag: addTagMutation.mutate,
    removeTag: removeTagMutation.mutate,
    isAdding: addTagMutation.isPending,
    isRemoving: removeTagMutation.isPending,
  };
}

import { useState, useRef, useCallback, KeyboardEvent } from "react";
import { X, Tag, Plus } from "lucide-react";
import { Input } from "@/components/ui/input";
import type { CandidateTag } from "@/hooks/useCandidateTags";

const PRESET_TAGS = [
  { tag: "Top Pick", color: "#10b981" },
  { tag: "Strong", color: "#6366f1" },
  { tag: "Follow Up", color: "#f59e0b" },
  { tag: "Phone Screen", color: "#3b82f6" },
  { tag: "On Hold", color: "#8b5cf6" },
  { tag: "Overqualified", color: "#ec4899" },
  { tag: "Remote Only", color: "#14b8a6" },
  { tag: "Needs Review", color: "#f97316" },
];

interface CandidateTagInputProps {
  resumeId: string;
  tags: CandidateTag[];
  onAdd: (params: { resumeId: string; tag: string; color?: string }) => void;
  onRemove: (tagId: string) => void;
  disabled?: boolean;
}

export default function CandidateTagInput({
  resumeId,
  tags,
  onAdd,
  onRemove,
  disabled = false,
}: CandidateTagInputProps) {
  const [inputValue, setInputValue] = useState("");
  const [showSuggestions, setShowSuggestions] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const existingTagNames = new Set(tags.map((t) => t.tag.toLowerCase()));

  const filteredSuggestions = PRESET_TAGS.filter(
    (p) =>
      !existingTagNames.has(p.tag.toLowerCase()) &&
      (inputValue === "" || p.tag.toLowerCase().includes(inputValue.toLowerCase()))
  );

  const handleAddTag = useCallback(
    (tag: string, color?: string) => {
      const trimmed = tag.trim();
      if (!trimmed || existingTagNames.has(trimmed.toLowerCase())) return;
      onAdd({ resumeId, tag: trimmed, color });
      setInputValue("");
      setShowSuggestions(false);
    },
    [resumeId, onAdd, existingTagNames]
  );

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter" && inputValue.trim()) {
      e.preventDefault();
      handleAddTag(inputValue.trim());
    }
    if (e.key === "Escape") {
      setShowSuggestions(false);
      inputRef.current?.blur();
    }
    if (e.key === "Backspace" && inputValue === "" && tags.length > 0) {
      const last = tags[tags.length - 1];
      onRemove(last.id);
    }
  };

  return (
    <div className="space-y-2">
      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider flex items-center gap-1">
        <Tag className="h-3 w-3" /> Tags
      </p>

      {/* Chip list */}
      <div className="flex flex-wrap gap-1.5 min-h-[28px]">
        {tags.map((t) => (
          <span
            key={t.id}
            className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium text-white"
            style={{ backgroundColor: t.color }}
          >
            {t.tag}
            {!disabled && (
              <button
                onClick={() => onRemove(t.id)}
                className="hover:opacity-70 transition-opacity ml-0.5"
                aria-label={`Remove tag ${t.tag}`}
              >
                <X className="h-2.5 w-2.5" />
              </button>
            )}
          </span>
        ))}
      </div>

      {/* Input + autocomplete */}
      {!disabled && (
        <div className="relative">
          <div className="flex items-center gap-1.5">
            <div className="relative flex-1">
              <Input
                ref={inputRef}
                value={inputValue}
                onChange={(e) => {
                  setInputValue(e.target.value);
                  setShowSuggestions(true);
                }}
                onFocus={() => setShowSuggestions(true)}
                onBlur={() => setTimeout(() => setShowSuggestions(false), 150)}
                onKeyDown={handleKeyDown}
                placeholder="Add tag…"
                className="h-7 text-xs pr-2"
                disabled={disabled}
              />
            </div>
            {inputValue.trim() && (
              <button
                className="flex items-center gap-0.5 text-xs text-primary hover:text-primary/80 transition-colors shrink-0"
                onMouseDown={(e) => {
                  e.preventDefault();
                  handleAddTag(inputValue.trim());
                }}
              >
                <Plus className="h-3 w-3" /> Add
              </button>
            )}
          </div>

          {/* Suggestions dropdown */}
          {showSuggestions && filteredSuggestions.length > 0 && (
            <div className="absolute z-50 top-full mt-1 w-full bg-popover border border-border rounded-md shadow-md overflow-hidden">
              {filteredSuggestions.slice(0, 6).map((p) => (
                <button
                  key={p.tag}
                  className="w-full flex items-center gap-2 px-3 py-1.5 text-xs hover:bg-muted/60 transition-colors text-left"
                  onMouseDown={(e) => {
                    e.preventDefault();
                    handleAddTag(p.tag, p.color);
                  }}
                >
                  <span
                    className="h-2 w-2 rounded-full shrink-0"
                    style={{ backgroundColor: p.color }}
                  />
                  {p.tag}
                </button>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { useState } from "react";
import { UserCheck, Loader2 } from "lucide-react";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import type { TeamMember } from "@/hooks/useTeam";

interface AssigneeSelectorProps {
  resumeId: string;
  assignedTo: string | null | undefined;
  members: TeamMember[];
  disabled?: boolean;
  onAssigned?: (userId: string | null) => void;
}

export default function AssigneeSelector({
  resumeId,
  assignedTo,
  members,
  disabled = false,
  onAssigned,
}: AssigneeSelectorProps) {
  const [saving, setSaving] = useState(false);

  const handleChange = async (value: string) => {
    const userId = value === "__none__" ? null : value;
    setSaving(true);
    try {
      const { error } = await (supabase as any)
        .from("resumes")
        .update({ assigned_to: userId })
        .eq("id", resumeId);
      if (error) throw error;
      onAssigned?.(userId);
      toast.success(userId ? "Assignee updated" : "Assignee removed");
    } catch {
      toast.error("Failed to update assignee");
    } finally {
      setSaving(false);
    }
  };

  const displayValue = assignedTo ?? "__none__";

  const getMemberLabel = (member: TeamMember) => {
    return member.email ?? `User ${member.user_id.slice(0, 8)}`;
  };

  return (
    <div className="space-y-2">
      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider flex items-center gap-1">
        <UserCheck className="h-3 w-3" /> Assigned To
      </p>
      <Select
        value={displayValue}
        onValueChange={handleChange}
        disabled={disabled || saving || members.length === 0}
      >
        <SelectTrigger className="h-8 text-xs">
          {saving ? (
            <span className="flex items-center gap-1.5 text-muted-foreground">
              <Loader2 className="h-3 w-3 animate-spin" />
              Saving…
            </span>
          ) : (
            <SelectValue placeholder={members.length === 0 ? "No team members" : "Unassigned"} />
          )}
        </SelectTrigger>
        <SelectContent>
          <SelectItem value="__none__" className="text-xs text-muted-foreground">
            Unassigned
          </SelectItem>
          {members.map((m) => (
            <SelectItem key={m.user_id} value={m.user_id} className="text-xs">
              {getMemberLabel(m)}
              {m.role === "owner" && (
                <span className="ml-1 text-[10px] text-muted-foreground">(owner)</span>
              )}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

